using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    private static int Charged(LoyaltyTier tier, int subtotalCents) =>
        new CalculateLoyaltyDiscount().Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier)).TotalCents;

    // Bronze customer is charged the Bronze price
    [Fact]
    public void S1_BronzeCustomerIsChargedTheBronzePrice() =>
        Assert.Equal(9500, Charged(LoyaltyTier.Bronze, 10000));

    // Silver customer is charged the Silver price
    [Fact]
    public void S2_SilverCustomerIsChargedTheSilverPrice() =>
        Assert.Equal(9000, Charged(LoyaltyTier.Silver, 10000));

    // Gold customer is charged the Gold price
    [Fact]
    public void S3_GoldCustomerIsChargedTheGoldPrice() =>
        Assert.Equal(8500, Charged(LoyaltyTier.Gold, 10000));

    // Bronze customer with a tiny basket is charged the full subtotal
    [Fact]
    public void S4_BronzeCustomerWithTinyBasketIsChargedTheFullSubtotal() =>
        Assert.Equal(7, Charged(LoyaltyTier.Bronze, 7));
}

